pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MyContract} from "../src/MyContract.sol";

contract InvMutTest is Test {
    MyContract c;
    address owner;

    function setUp() public { c = new MyContract(); owner = address(this); }

    function testFuzz_property(address receiver, uint256 amount) public {

        vm.startPrank(owner);
        bool ok;
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();

        if (amount == 0) {
            assertTrue(!ok);
        } else {
            assertTrue(true);
        }
    }
}
